const result = $input.first().json.result || [];
const assets = [];
const set = new Set();
for (const a of result) {
  if (a.current_owner == null) continue;
  assets.push({ code: a.code, owner_id: a.current_owner });
  set.add(a.current_owner);
}
return [{ json: { assets, owner_ids: [...set], n_assets: assets.length, n_owners: set.size } }];

const emps = $input.all().map(i => i.json);
const assets = $('Extraer activos y titulares').first().json.assets || [];
function titleCase(s){
  return String(s||'').toLowerCase().split(/\s+/).filter(Boolean)
    .map(w => w.charAt(0).toUpperCase()+w.slice(1)).join(' ');
}
const byOwner = {};
for (const e of emps){
  const login = String(e.login||'').trim().toLowerCase();
  if (!login) continue;
  byOwner[e.party_id] = { email: login+'@guayas.gob.ec', first_name: titleCase(e.nombres), last_name: titleCase(e.apellidos) };
}
const rows = [];
for (const a of assets){
  const o = byOwner[a.owner_id];
  if (o && o.email) rows.push({ snipe_asset_tag: a.code, email: o.email, first_name: o.first_name, last_name: o.last_name });
}
return [{ json: { payload: JSON.stringify(rows), total: rows.length } }];

