INSERT INTO staging_titular (snipe_asset_tag, email, first_name, last_name)
SELECT x.snipe_asset_tag, x.email, x.first_name, x.last_name
FROM jsonb_to_recordset($1::jsonb) AS x(snipe_asset_tag text, email text, first_name text, last_name text);

