const applied = $('Consolidar resultados').all();
const diffCount = (()=>{ try { return $('Detectar cambios de titular').all().length; } catch(e){ return 0; } })();
const omitidos = (()=>{ try { return $('Contar activos sin mapeo').first().json.omitidos ?? 0; } catch(e){ return 0; } })();
const cambios = diffCount;
const ok = applied.filter(i=>i.json.status==='ok').length;
const errores = applied.filter(i=>i.json.status==='error').length;
const usuarios_nuevos = applied.filter(i=>i.json.status==='ok' && i.json.created_user).length;
const summary = { cambios, aplicados: ok, errores, omitidos, usuarios_nuevos };
return [{ json: summary }];
